// P0.18 — shared worker error path. When any workflow execution fails, this
// handler is invoked by n8n's error trigger. It recovers the job_id from the
// failed execution's error payload (deep walk + full-payload UUID scan) and,
// if found, calls fail_job() so the job never stays RUNNING forever. If no
// job_id can be recovered it emits zero items (graceful no-op — the DB
// lease/max_attempts recovery is the secondary net).
const err = $json || {};
const execution = err.execution || {};
const failed = execution.lastNodeExecuted || '';

let jobId = null;
// 1) deep walk for a job_id / jobId property.
function findJobId(o, depth) {
  if (!o || typeof o !== 'object' || depth > 10) return null;
  if (o.job_id) return o.job_id;
  if (o.jobId) return o.jobId;
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (Array.isArray(v)) {
      for (const it of v) { const r = findJobId(it, depth + 1); if (r) return r; }
    } else if (v && typeof v === 'object') {
      const r = findJobId(v, depth + 1); if (r) return r;
    }
  }
  return null;
}
// 2) full-payload scan: the failing HTTP node carries job_id in its URL / body,
//    so a regex over the whole serialized payload is the deterministic fallback.
function scanPayload(o) {
  try {
    const dump = JSON.stringify(o || {});
    let m = dump.match(/"?job_?id"?\s*[:=]\s*"?([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i);
    if (m) return m[1];
    m = dump.match(/job_?id=[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
    if (m) return m[0].split('=')[1];
  } catch (e) { /* ignore */ }
  return null;
}
jobId = findJobId(err, 0) || scanPayload(err);
if (!jobId) return [];

const errorText = String((err.error && err.error.message) || err.error || 'workflow execution failed');
return [{ json: { jobId: jobId, error: 'WORKFLOW_ERROR:' + failed + ' -> ' + errorText.slice(0, 500) } }];
